// План specs/mobile-nav.md 1.1–1.4 (кейс .qa/tests/mobile-nav/MN-01). Admin, компания «test». Только просмотр (@prod-safe):
// меню открывается и проверяется, пункты не нажимаются. 375×812 — iPhone (WebKit), 390×844 — Chrome (Android-прогон).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, ITEMS, Lang, PHONES, boxes, expectSingleColumn, expectVerticalOrder, openMoreMenu, restoreCompany } from './mobile-nav-helpers';

test.use({ storageState: ADMIN_STATE });

for (const phone of PHONES) {
  test.describe(`Phone ${phone.label}: "More" menu is a single column (#e9cbda)`, () => {
    test.use({ viewport: phone.viewport });

    for (const lang of ['en', 'he'] as Lang[]) {
      test(`More menu ${phone.label} ${lang.toUpperCase()}: all ${ITEMS[lang].length} admin items in one column, one under another, desktop order #e9cbda ${phone.tag} @prod-safe`, async ({ page }) => {
        try {
          const { items } = await openMoreMenu(page, lang);
          const bs = await boxes(items);
          // «מה רצוי»: כל פריטי התפריט מוצגים בעמודה אחת, אחד מתחת לשני — одинаковые x и ширина.
          expectSingleColumn(bs);
          // «כמו בדסקטופ»: порядок Home … Support Console сверху вниз, без наложения.
          expectVerticalOrder(bs);
          expect(bs.length).toBe(ITEMS[lang].length);
        } finally {
          await restoreCompany(page);
        }
      });
    }
  });
}
